function isRealBoundary(edges, exportsOf, a, b) {
  // Write your solution here
  const cross = edges.filter((e) => a.includes(e.from) && b.includes(e.to));
  return { real: true, direction: cross.length ? 'a->b' : 'none', violations: [] };
}

